BEGIN;
DO $$
DECLARE
    v_author_id uuid;
    v_category_id uuid := '07fa3d69-7455-478f-9f82-b3c350b58016';
    v_roadmap_id uuid := 'c7300001-6b87-4d48-9812-000000000003';
BEGIN
    SELECT u."Id" INTO v_author_id FROM gdsc."Users" u JOIN gdsc."UserRoles" ur ON u."Id" = ur."UserId" JOIN gdsc."Roles" r ON ur."RoleId" = r."Id" WHERE r."NormalizedName" = 'ADMIN' AND u."IsDeleted" = false ORDER BY u."Id" LIMIT 1;
    IF v_author_id IS NULL THEN RAISE NOTICE 'No admin'; RETURN; END IF;
    DELETE FROM gdsc."RoadmapEdges" WHERE "RoadmapId" = v_roadmap_id;
    DELETE FROM gdsc."RoadmapNodes" WHERE "RoadmapId" = v_roadmap_id;
END $$;
COMMIT;
